#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    if (!(cin >> s)) return 0;
    int cnt[4] = {0, 0, 0, 0};
    bool dup[4] = {false, false, false, false};
    bool seen[4][14] = {};
    auto idx = [](char c) -> int {
        switch (c) {
            case 'C': return 0;
            case 'E': return 1;
            case 'U': return 2;
            case 'P': return 3;
        }
        return -1;
    };
    for (size_t i = 0; i + 2 < s.size(); i += 3) {
        int v = (s[i] - '0') * 10 + (s[i + 1] - '0');
        int n = idx(s[i + 2]);
        if (n < 0) continue;
        if (seen[n][v]) dup[n] = true;
        seen[n][v] = true;
        cnt[n]++;
    }
    const char* res[4];
    for (int i = 0; i < 4; i++) {
        static char buf[8];
        if (dup[i]) res[i] = "erro";
        else if (cnt[i] == 13) res[i] = "0";
        else {
            snprintf(buf, sizeof(buf), "%d", 13 - cnt[i]);
            res[i] = buf;
        }
        cout << res[i] << "\n";
    }
    return 0;
}
